<script setup lang="ts">import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {useAuthStore} from '../stores/auth';const form=reactive({username:'admin',password:'ChangeMe123!'}),loading=ref(false),router=useRouter(),auth=useAuthStore();async function submit(){loading.value=true;try{await auth.login(form.username,form.password);await router.push('/dashboard')}finally{loading.value=false}}</script>
<template><main class="login"><el-card><h1>AML 合规管理平台</h1><p class="muted">本地教学与演示环境</p><el-form label-position="top" @submit.prevent="submit"><el-form-item label="用户名"><el-input v-model="form.username"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password/></el-form-item><el-button type="primary" native-type="submit" :loading="loading">登录</el-button></el-form><p class="warning">演示账户仅供本地开发；生产环境必须关闭 dev 配置并更换密钥。</p></el-card></main></template>
<style scoped>.login{min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#12213d,#245f8e)}.el-card{width:420px}h1{margin-bottom:4px}.el-button{width:100%}.warning{font-size:12px;margin-top:18px}</style>
